function validate([nums, queries]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 strings.';
  const length = nums[0].length;
  if (length < 1 || length > 100) return 'Each string has 1 to 100 digits.';
  if (nums.some(s => typeof s !== 'string' || s.length !== length)) return 'All strings in nums must have the same length.';
  if (nums.some(s => !/^[0-9]+$/.test(s))) return 'Strings may contain only digits.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100) return 'queries needs 1 to 100 pairs.';
  for (const q of queries) {
    if (!Array.isArray(q) || q.length !== 2) return 'Each query is a pair [k, trim].';
    const [k, trim] = q;
    if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k must be between 1 and nums.length.';
    if (!Number.isInteger(trim) || trim < 1 || trim > length) return 'trim must be between 1 and the string length.';
  }
  return null;
}

