function smallestTrimmedNumbers(nums, queries) {
  const length = nums[0].length;
  const answer = [];

  for (const [k, trim] of queries) {
    const trimmed = nums.map(num => num.slice(length - trim));
    const order = nums.map((_, index) => index);
    order.sort((i, j) => {
      if (trimmed[i] < trimmed[j]) {
        return -1;
      }
      if (trimmed[i] > trimmed[j]) {
        return 1;
      }
      return i - j;
    });
    answer.push(order[k - 1]);
  }
  return answer;
}

