function smallestTrimmedNumbers(nums, queries) {
  // Compare two digit strings by numeric value: drop leading zeros, then shorter is smaller.
  const value = s => s.replace(/^0+/, '');
  const less = (a, b) => {
    const x = value(a), y = value(b);
    if (x.length !== y.length) return x.length < y.length;
    for (let p = 0; p < x.length; p++) if (x[p] !== y[p]) return x[p] < y[p];
    return false;
  };
  const result = [];
  for (const [k, trim] of queries) {
    const cut = nums.map(s => s.substring(s.length - trim));
    // The k-th smallest is the index with exactly k - 1 indices ranked before it.
    for (let i = 0; i < nums.length; i++) {
      let before = 0;
      for (let j = 0; j < nums.length; j++) {
        if (j === i) continue;
        if (less(cut[j], cut[i]) || (!less(cut[i], cut[j]) && j < i)) before++;
      }
      if (before === k - 1) { result.push(i); break; }
    }
  }
  return result;
}

