function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 100 : 1 + Math.floor(rand() * 6);
  const length = large ? 100 : 1 + Math.floor(rand() * 4);
  // A small digit alphabet makes equal trimmed values (and the index tie-break) common.
  const digits = rand() < 0.5 ? 2 + Math.floor(rand() * 2) : 10;
  const nums = Array.from({ length: n }, () => {
    let s = '';
    for (let p = 0; p < length; p++) s += String(Math.floor(rand() * digits));
    return s;
  });
  const count = large ? 100 : 1 + Math.floor(rand() * 5);
  const queries = Array.from({ length: count }, () => [1 + Math.floor(rand() * n), 1 + Math.floor(rand() * length)]);
  return [nums, queries];
}
